import type { HTMLAttributes } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * Spinner.
 *
 * Something is happening and the answer has not arrived. It carries no text of
 * its own - what is loading is the product's word, not the system's - but it
 * does have to say *something* to a screen reader, or a page that is busy is
 * silently identical to a page that is empty.
 *
 * Under `prefers-reduced-motion` the theme stops the animation. That is not a
 * detail: for some readers a spinning thing is not decoration but a symptom.
 * A stopped spinner still says "busy" through `role`, which is the part that
 * carried the meaning all along.
 */
export const spinnerVariants = cva('inline-block animate-spin rounded-full border-2 border-current', {
  variants: {
    size: {
      sm: 'size-3.5 border-[1.5px]',
      md: 'size-4',
      lg: 'size-6',
    },
    tone: {
      /* Follows the text it sits in. */
      current: 'text-current',
      dim: 'text-dim',
      accent: 'text-accent',
    },
  },
  defaultVariants: { size: 'md', tone: 'current' },
})

export interface SpinnerProps
  extends HTMLAttributes<HTMLSpanElement>,
    VariantProps<typeof spinnerVariants> {
  /** What is being waited for, for a screen reader. The product's word. */
  label?: string
}

export function Spinner({ size, tone, label, className, ...props }: SpinnerProps) {
  return (
    <span role="status" aria-live="polite" className={cn('inline-flex items-center gap-2', className)} {...props}>
      <span
        // The gap in the ring is what makes the rotation visible.
        className={cn(spinnerVariants({ size, tone }), 'border-r-transparent')}
        aria-hidden
      />
      {label && <span className="sr-only">{label}</span>}
    </span>
  )
}

import { useCallback, useLayoutEffect, useRef, type Ref, type TextareaHTMLAttributes } from 'react'
import { cn } from 'dowel-ui'
import { fieldClasses } from './input'

/*
 * Textarea.
 *
 * A multi-line field that can grow with what is typed into it, which is the
 * only interesting part: a fixed box makes someone scroll inside a scroll,
 * and a box that grows without limit pushes the button they are trying to
 * reach off the screen. `autoResize` grows it; `maxRows` says when to stop
 * and let it scroll after all.
 *
 * The measurement is the usual trick and worth stating: height is reset to
 * `auto` before reading `scrollHeight`, because a box already tall enough
 * reports its own height and never shrinks back.
 */
export interface TextareaProps extends TextareaHTMLAttributes<HTMLTextAreaElement> {
  ref?: Ref<HTMLTextAreaElement>
  /** Grow to fit the content instead of scrolling. */
  autoResize?: boolean
  /** Stop growing here, in lines, and scroll instead. */
  maxRows?: number
}

export function Textarea({
  className,
  ref,
  autoResize = false,
  maxRows,
  onChange,
  ...props
}: TextareaProps) {
  const own = useRef<HTMLTextAreaElement>(null)

  const resize = useCallback(() => {
    const element = own.current
    if (!element || !autoResize) return

    // Reset first: a box that is already tall enough reports its own height as
    // `scrollHeight` and would never shrink again.
    element.style.height = 'auto'

    const styles = getComputedStyle(element)
    const lineHeight = Number.parseFloat(styles.lineHeight) || 0
    const vertical =
      Number.parseFloat(styles.paddingTop) +
      Number.parseFloat(styles.paddingBottom) +
      Number.parseFloat(styles.borderTopWidth) +
      Number.parseFloat(styles.borderBottomWidth)

    const wanted = element.scrollHeight
    const ceiling = maxRows && lineHeight ? maxRows * lineHeight + vertical : Infinity

    element.style.height = `${Math.min(wanted, ceiling)}px`
    element.style.overflowY = wanted > ceiling ? 'auto' : 'hidden'
  }, [autoResize, maxRows])

  // Before paint, so the field never appears at the wrong height and then
  // jumps - including on the first render, when it may already have a value.
  useLayoutEffect(resize, [resize, props.value, props.defaultValue])

  return (
    <textarea
      ref={(element) => {
        own.current = element
        if (typeof ref === 'function') ref(element)
        else if (ref) ref.current = element
      }}
      onChange={(event) => {
        resize()
        onChange?.(event)
      }}
      className={cn(fieldClasses, autoResize ? 'resize-none' : 'resize-y', className)}
      {...props}
    />
  )
}

import type { HTMLAttributes } from 'react'
import { cn } from 'dowel-ui'

/*
 * Truncate.
 *
 * Text that does not fit, cut with an ellipsis - and, importantly, still
 * readable in full: the element carries its own text as a `title`, so hovering
 * shows what was cut. Every product wrote the one-line version of this and
 * none of them remembered the title.
 *
 * `lines` truncates after that many instead of one, which needs a different
 * mechanism (`line-clamp`) rather than a different value.
 */
export interface TruncateProps extends HTMLAttributes<HTMLSpanElement> {
  /** The text. A string, because the component has to be able to put it in a
   * `title` - arbitrary children could not be. */
  children: string
  /** Cut after this many lines. One by default. */
  lines?: number
  /** Say what the full text is on hover. On by default; turn it off where the
   * text is already visible elsewhere, or the tooltip is noise. */
  title?: string | undefined
}

export function Truncate({ children, lines = 1, className, title, ...props }: TruncateProps) {
  return (
    <span
      // The browser shows this only when the text is actually cut, so it costs
      // nothing when everything fits.
      title={title ?? children}
      className={cn(
        lines === 1 ? 'block truncate' : 'block overflow-hidden',
        className,
      )}
      style={
        lines > 1
          ? { display: '-webkit-box', WebkitLineClamp: lines, WebkitBoxOrient: 'vertical' }
          : undefined
      }
      {...props}
    >
      {children}
    </span>
  )
}
